<div class="topbar"><h1><?= $isNew?'New customer':'Edit customer' ?></h1><a class="btn btn-ghost" href="<?=url('/admin/customers')?>">Back</a></div><?php $errors=flash('errors',[]); if($errors):?><div class="alert alert-error"><?php foreach($errors as $x):?><div><?=e($x)?></div><?php endforeach;?></div><?php endif;?><form class="card form-grid" method="post" action="<?=url($isNew?'/admin/customers':'/admin/customers/'.$row['id'])?>"><?=csrf_field()?><label>Code<input name="code" value="<?=e($row['code']??'')?>" required></label><label>Company name<input name="company_name" value="<?=e($row['company_name']??'')?>" required></label><label>Contact name<input name="contact_name" value="<?=e($row['contact_name']??'')?>"></label><label>Email<input type="email" name="email" value="<?=e($row['email']??'')?>"></label><label>Phone<input name="phone" value="<?=e($row['phone']??'')?>"></label><label>Currency<select name="default_currency"><?php foreach(Money::CURRENCIES as $c=>$v):?><option <?=($row['default_currency']??'AED')===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select></label><label class="span2">Address<textarea name="address"><?=e($row['address']??'')?></textarea></label><label>Status<select name="status"><option value="active" <?=($row['status']??'active')==='active'?'selected':''?>>Active</option><option value="inactive">Inactive</option></select></label><button class="btn btn-primary">Save customer</button></form>
